function specialistOutcomeRecord(raw, roundCtx, name) {
    if (!raw) return { reason: 'no candidates file' };
    var record = null;
    try {
        record = candidatesModule.candidatesRecordFromPayload(JSON.parse(raw));
    } catch (eParse) {
